import numpy as np

cases = []

# 1) gh-16352 example: should overflow when converting h -> ns
expr1 = lambda: np.array(['2367-12-31 12:00:00'], dtype='datetime64[h]').astype('datetime64[ns]')
cases.append(('ex_h_to_ns_overflow', expr1))

# 2) large scalar seconds -> ns should overflow
expr2 = lambda: np.datetime64('3000-01-01', 's').astype('datetime64[ns]')
cases.append(('ex_s_to_ns_scalar_overflow', expr2))

# 3) near int64 min seconds -> minutes/month conversion path should overflow somewhere
expr3 = lambda: np.datetime64(np.iinfo(np.int64).min + 1, 's').astype('M8[m]')
cases.append(('ex_int64min_plus_1_s_to_M8m_overflow', expr3))

# 4) timedelta seconds -> ns overflow
expr4 = lambda: np.timedelta64(9223372037, 's').astype('timedelta64[ns]')
cases.append(('ex_timedelta_s_to_ns_overflow', expr4))

# 5) non-overflow sanity: should succeed
expr5 = lambda: np.timedelta64(9223372036, 's').astype('timedelta64[ns]')
cases.append(('ex_timedelta_s_to_ns_valid', expr5))

results = {}
for name, fn in cases:
    try:
        v = fn()
        # Convert to a repr-friendly value
        if isinstance(v, np.ndarray):
            results[name] = {'ok': True, 'repr': repr(v), 'dtype': str(v.dtype)}
        else:
            results[name] = {'ok': True, 'repr': repr(v), 'dtype': str(getattr(v, 'dtype', ''))}
    except Exception as e:
        results[name] = {'ok': False, 'exc_type': type(e).__name__, 'exc_msg': str(e)}

# Emit individual probes so the harness records them per case
for k, v in results.items():
    probe(k, v)

